class _UniffiConverterString:
    @staticmethod
    def check_lower(value):
        if not isinstance(value, str):
            raise TypeError("argument must be str, not {}".format(type(value).__name__))
        return value

    @staticmethod
    def read(buf):
        size = buf.read_i32()
        if size < 0:
            raise InternalError("Unexpected negative string length")
        utf8_bytes = buf.read(size)
        return utf8_bytes.decode("utf-8")

    @staticmethod
    def write(value, buf):
        utf8_bytes = value.encode("utf-8")
        buf.write_i32(len(utf8_bytes))
        buf.write(utf8_bytes)

    @staticmethod
    def lift(buf):
        with buf.consume_with_stream() as stream:
            return stream.read(stream.remaining()).decode("utf-8")

    @staticmethod
    def lower(value):
        with _UniffiRustBuffer.alloc_with_builder() as builder:
            builder.write(value.encode("utf-8"))
            return builder.finalize()


class Card:
    id: "int"
    key: "str"
    arcana: "ArcanaType"
    suit: "typing.Optional[Suit]"
    rank: "typing.Optional[Rank]"
    element: "Element"
    name_en: "str"
    name_zh: "str"
    astrology: "typing.Optional[str]"
    hebrew_letter: "typing.Optional[str]"
    facets: "CardFacets"
    def __init__(self, *, id: "int", key: "str", arcana: "ArcanaType", suit: "typing.Optional[Suit]", rank: "typing.Optional[Rank]", element: "Element", name_en: "str", name_zh: "str", astrology: "typing.Optional[str]", hebrew_letter: "typing.Optional[str]", facets: "CardFacets"):
        self.id = id
        self.key = key
        self.arcana = arcana
        self.suit = suit
        self.rank = rank
        self.element = element
        self.name_en = name_en
        self.name_zh = name_zh
        self.astrology = astrology
        self.hebrew_letter = hebrew_letter
        self.facets = facets

    def __str__(self):
        return "Card(id={}, key={}, arcana={}, suit={}, rank={}, element={}, name_en={}, name_zh={}, astrology={}, hebrew_letter={}, facets={})".format(self.id, self.key, self.arcana, self.suit, self.rank, self.element, self.name_en, self.name_zh, self.astrology, self.hebrew_letter, self.facets)

    def __eq__(self, other):
        if self.id != other.id:
            return False
        if self.key != other.key:
            return False
        if self.arcana != other.arcana:
            return False
        if self.suit != other.suit:
            return False
        if self.rank != other.rank:
            return False
        if self.element != other.element:
            return False
        if self.name_en != other.name_en:
            return False
        if self.name_zh != other.name_zh:
            return False
        if self.astrology != other.astrology:
            return False
        if self.hebrew_letter != other.hebrew_letter:
            return False
        if self.facets != other.facets:
            return False
        return True

