        _UniffiConverterUInt8.check_lower(value.id)
        _UniffiConverterString.check_lower(value.key)
        _UniffiConverterTypeArcanaType.check_lower(value.arcana)
        _UniffiConverterOptionalTypeSuit.check_lower(value.suit)
        _UniffiConverterOptionalTypeRank.check_lower(value.rank)
