        _UniffiConverterString.check_lower(value.name_en)
        _UniffiConverterString.check_lower(value.name_zh)
        _UniffiConverterOptionalString.check_lower(value.astrology)
        _UniffiConverterOptionalString.check_lower(value.hebrew_letter)
        _UniffiConverterTypeCardFacets.check_lower(value.facets)

