# TarotError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class TarotError(Exception):
    pass

_UniffiTempTarotError = TarotError

class TarotError:  # type: ignore
    class InvalidSeed(_UniffiTempTarotError):
        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            if not isinstance(values[0], str):
                raise TypeError(f"unexpected type for tuple element 0 - expected 'str', got '{type(values[0])}'")
            super().__init__(", ".join(map(repr, values)))
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

        def __repr__(self):
            return "TarotError.InvalidSeed({})".format(str(self))
    _UniffiTempTarotError.InvalidSeed = InvalidSeed # type: ignore
    class CardIndexOutOfBounds(_UniffiTempTarotError):
        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            if not isinstance(values[0], int):
                raise TypeError(f"unexpected type for tuple element 0 - expected 'int', got '{type(values[0])}'")
            super().__init__(", ".join(map(repr, values)))
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

        def __repr__(self):
            return "TarotError.CardIndexOutOfBounds({})".format(str(self))
    _UniffiTempTarotError.CardIndexOutOfBounds = CardIndexOutOfBounds # type: ignore
    class DuplicateCardDraw(_UniffiTempTarotError):
        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            if not isinstance(values[0], int):
                raise TypeError(f"unexpected type for tuple element 0 - expected 'int', got '{type(values[0])}'")
            super().__init__(", ".join(map(repr, values)))
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

        def __repr__(self):
            return "TarotError.DuplicateCardDraw({})".format(str(self))
    _UniffiTempTarotError.DuplicateCardDraw = DuplicateCardDraw # type: ignore
    class SpreadSlotOverflow(_UniffiTempTarotError):
        def __init__(self, requested, capacity):
            super().__init__(", ".join([
                "requested={!r}".format(requested),
                "capacity={!r}".format(capacity),
            ]))
            self.requested = requested
            self.capacity = capacity

        def __repr__(self):
            return "TarotError.SpreadSlotOverflow({})".format(str(self))
    _UniffiTempTarotError.SpreadSlotOverflow = SpreadSlotOverflow # type: ignore
    class ConstraintViolation(_UniffiTempTarotError):
        def __init__(self, slot_id, required, actual):
            super().__init__(", ".join([
                "slot_id={!r}".format(slot_id),
                "required={!r}".format(required),
                "actual={!r}".format(actual),
            ]))
            self.slot_id = slot_id
            self.required = required
            self.actual = actual

        def __repr__(self):
            return "TarotError.ConstraintViolation({})".format(str(self))
    _UniffiTempTarotError.ConstraintViolation = ConstraintViolation # type: ignore
    class SpreadNotFound(_UniffiTempTarotError):
        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            if not isinstance(values[0], str):
                raise TypeError(f"unexpected type for tuple element 0 - expected 'str', got '{type(values[0])}'")
            super().__init__(", ".join(map(repr, values)))
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

        def __repr__(self):
            return "TarotError.SpreadNotFound({})".format(str(self))
    _UniffiTempTarotError.SpreadNotFound = SpreadNotFound # type: ignore
    class DeserializationError(_UniffiTempTarotError):
        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            if not isinstance(values[0], str):
                raise TypeError(f"unexpected type for tuple element 0 - expected 'str', got '{type(values[0])}'")
            super().__init__(", ".join(map(repr, values)))
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

        def __repr__(self):
            return "TarotError.DeserializationError({})".format(str(self))
    _UniffiTempTarotError.DeserializationError = DeserializationError # type: ignore
    class AiProviderUnavailable(_UniffiTempTarotError):
        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            if not isinstance(values[0], str):
                raise TypeError(f"unexpected type for tuple element 0 - expected 'str', got '{type(values[0])}'")
            super().__init__(", ".join(map(repr, values)))
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

        def __repr__(self):
            return "TarotError.AiProviderUnavailable({})".format(str(self))
    _UniffiTempTarotError.AiProviderUnavailable = AiProviderUnavailable # type: ignore
    class Unauthorized(_UniffiTempTarotError):
        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            if not isinstance(values[0], str):
                raise TypeError(f"unexpected type for tuple element 0 - expected 'str', got '{type(values[0])}'")
            super().__init__(", ".join(map(repr, values)))
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

        def __repr__(self):
            return "TarotError.Unauthorized({})".format(str(self))
    _UniffiTempTarotError.Unauthorized = Unauthorized # type: ignore

TarotError = _UniffiTempTarotError # type: ignore
del _UniffiTempTarotError


class _UniffiConverterTypeTarotError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return TarotError.InvalidSeed(
                _UniffiConverterString.read(buf),
            )
        if variant == 2:
            return TarotError.CardIndexOutOfBounds(
                _UniffiConverterUInt8.read(buf),
            )
        if variant == 3:
            return TarotError.DuplicateCardDraw(
                _UniffiConverterUInt8.read(buf),
            )
        if variant == 4:
            return TarotError.SpreadSlotOverflow(
                _UniffiConverterUInt64.read(buf),
                _UniffiConverterUInt64.read(buf),
            )
        if variant == 5:
            return TarotError.ConstraintViolation(
                _UniffiConverterUInt8.read(buf),
                _UniffiConverterString.read(buf),
                _UniffiConverterString.read(buf),
            )
        if variant == 6:
            return TarotError.SpreadNotFound(
                _UniffiConverterString.read(buf),
            )
        if variant == 7:
            return TarotError.DeserializationError(
                _UniffiConverterString.read(buf),
            )
        if variant == 8:
            return TarotError.AiProviderUnavailable(
                _UniffiConverterString.read(buf),
            )
        if variant == 9:
            return TarotError.Unauthorized(
                _UniffiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if isinstance(value, TarotError.InvalidSeed):
            _UniffiConverterString.check_lower(value._values[0])
            return
        if isinstance(value, TarotError.CardIndexOutOfBounds):
            _UniffiConverterUInt8.check_lower(value._values[0])
            return
        if isinstance(value, TarotError.DuplicateCardDraw):
            _UniffiConverterUInt8.check_lower(value._values[0])
            return
        if isinstance(value, TarotError.SpreadSlotOverflow):
            _UniffiConverterUInt64.check_lower(value.requested)
            _UniffiConverterUInt64.check_lower(value.capacity)
            return
        if isinstance(value, TarotError.ConstraintViolation):
            _UniffiConverterUInt8.check_lower(value.slot_id)
            _UniffiConverterString.check_lower(value.required)
            _UniffiConverterString.check_lower(value.actual)
            return
        if isinstance(value, TarotError.SpreadNotFound):
            _UniffiConverterString.check_lower(value._values[0])
            return
        if isinstance(value, TarotError.DeserializationError):
            _UniffiConverterString.check_lower(value._values[0])
            return
        if isinstance(value, TarotError.AiProviderUnavailable):
            _UniffiConverterString.check_lower(value._values[0])
            return
        if isinstance(value, TarotError.Unauthorized):
            _UniffiConverterString.check_lower(value._values[0])
            return

    @staticmethod
    def write(value, buf):
        if isinstance(value, TarotError.InvalidSeed):
            buf.write_i32(1)
            _UniffiConverterString.write(value._values[0], buf)
        if isinstance(value, TarotError.CardIndexOutOfBounds):
            buf.write_i32(2)
            _UniffiConverterUInt8.write(value._values[0], buf)
        if isinstance(value, TarotError.DuplicateCardDraw):
            buf.write_i32(3)
            _UniffiConverterUInt8.write(value._values[0], buf)
        if isinstance(value, TarotError.SpreadSlotOverflow):
            buf.write_i32(4)
            _UniffiConverterUInt64.write(value.requested, buf)
            _UniffiConverterUInt64.write(value.capacity, buf)
        if isinstance(value, TarotError.ConstraintViolation):
            buf.write_i32(5)
            _UniffiConverterUInt8.write(value.slot_id, buf)
            _UniffiConverterString.write(value.required, buf)
            _UniffiConverterString.write(value.actual, buf)
        if isinstance(value, TarotError.SpreadNotFound):
            buf.write_i32(6)
            _UniffiConverterString.write(value._values[0], buf)
        if isinstance(value, TarotError.DeserializationError):
            buf.write_i32(7)
            _UniffiConverterString.write(value._values[0], buf)
        if isinstance(value, TarotError.AiProviderUnavailable):
            buf.write_i32(8)
            _UniffiConverterString.write(value._values[0], buf)
        if isinstance(value, TarotError.Unauthorized):
            buf.write_i32(9)
            _UniffiConverterString.write(value._values[0], buf)



class _UniffiConverterOptionalUInt8(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        if value is not None:
            _UniffiConverterUInt8.check_lower(value)

    @classmethod
    def write(cls, value, buf):
        if value is None:
            buf.write_u8(0)
            return

        buf.write_u8(1)
        _UniffiConverterUInt8.write(value, buf)

    @classmethod
    def read(cls, buf):
        flag = buf.read_u8()
        if flag == 0:
            return None
        elif flag == 1:
            return _UniffiConverterUInt8.read(buf)
        else:
            raise InternalError("Unexpected flag byte for optional type")



