# Async support

def draw_reading_session(spread_id: "str",question: "typing.Optional[str]",seed_hex: "typing.Optional[str]",reversal_rate: "float") -> "ReadingSession":
    """
    UniFFI Exported: Draws a deterministic reading session
    """

    _UniffiConverterString.check_lower(spread_id)
    
    _UniffiConverterOptionalString.check_lower(question)
    
    _UniffiConverterOptionalString.check_lower(seed_hex)
    
    _UniffiConverterFloat.check_lower(reversal_rate)
    
    return _UniffiConverterTypeReadingSession.lift(_uniffi_rust_call_with_error(_UniffiConverterTypeTarotError,_UniffiLib.uniffi_taroturn_core_fn_func_draw_reading_session,
        _UniffiConverterString.lower(spread_id),
        _UniffiConverterOptionalString.lower(question),
        _UniffiConverterOptionalString.lower(seed_hex),
        _UniffiConverterFloat.lower(reversal_rate)))


def generate_random_seed() -> "str":
    """
    UniFFI Exported: Generates a 64-character cryptographic CSPRNG seed
    """

    return _UniffiConverterString.lift(_uniffi_rust_call_with_error(_UniffiConverterTypeTarotError,_UniffiLib.uniffi_taroturn_core_fn_func_generate_random_seed,))


def get_card_by_id(card_id: "int") -> "Card":
    """
    UniFFI Exported: Retrieves a card archetype definition by card ID (0..77)
    """

    _UniffiConverterUInt8.check_lower(card_id)
    
    return _UniffiConverterTypeCard.lift(_uniffi_rust_call_with_error(_UniffiConverterTypeTarotError,_UniffiLib.uniffi_taroturn_core_fn_func_get_card_by_id,
        _UniffiConverterUInt8.lower(card_id)))


def get_taroturn_version() -> "str":
    """
    UniFFI Exported: Returns static library version string
    """

    return _UniffiConverterString.lift(_uniffi_rust_call(_UniffiLib.uniffi_taroturn_core_fn_func_get_taroturn_version,))


